// CSD_RATIONALE_BEGIN
// Root cause of attempt 63's 0.0%: `RenderedEndsWith` fires on EVERY rendered `<<`,
// causing the strategy to enter constrained mode ~22 times per example. The parser closes
// each span after the first complete prefix (often a single identifier), so every span
// is 1 token. The evaluator extracts the LAST visible span, which is always a single
// trivial token—never the complete answer.
//
// Root cause confirmed by diagnostics:
//   "tiny_span_dominant: yes (94%)" — avg visible span length 1.14 tokens
//   "syntax_valid_semantic_mismatch: 48/49" — syntax fine, but last span is wrong fragment
//
// Fix: Two-phase strategy.
// Phase 1: Generate ~85% of budget UNCONSTRAINED. Do NOT check RenderedEndsWith; do NOT
//   enter constrained mode. The model writes its full reasoning (may include `<<>>` spans
//   naturally as unconstrained tokens—fine, they are evaluated but the LAST span wins).
// Phase 2 (remaining ~15% budget): Force-open exactly ONE constrained span via
//   OpenConstrainedSpan, then drive AdaptiveConstrainedStep until IsCompletePrefix,
//   then CloseConstrainedSpan. This guarantees the LAST visible span is the
//   parser-controlled, complete arithmetic expression—the actual final answer.
// CloseSpanWithinBudget is used as emergency close when ≤3 steps remain.
// Guidance is changed to discourage wrapping of intermediate terms and instead
// encourage writing the complete final expression in ONE << >> span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (unconstrained): insideConstrainedOut never becomes true inside this loop
//   (no RenderedEndsWith check; loop guard requires !insideConstrainedOut). On entry, if
//   insideConstrained is true, loop guard is false so it is skipped entirely; the
//   precondition guarantees parser.IsValidPrefix(currentConstrained). No mutation of
//   inside/current vars occurs in Phase 1, so the invariant is preserved throughout.
//
//   Phase 2 (OpenConstrainedSpan): sets insideConstrainedOut := true and
//   currentConstrainedOut := []; parser.IsValidPrefix([]) holds by precondition.
//
//   Phase 3 — CloseConstrainedSpan branch: sets insideConstrainedOut := false, making
//   the implication vacuously true; currentConstrainedOut := [].
//   Phase 3 — CloseSpanWithinBudget branch: postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 3 — AdaptiveConstrainedStep branch: the helper hard-masks to parser-valid next
//   tokens, so next is EOS or a parser-valid continuation. AppendConstrainedToken extends
//   currentConstrainedOut by exactly that token while preserving parser.IsValidPrefix. EOS
//   breaks without appending, leaving the invariant intact.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Initialization: equality holds (generated = generatedPrefix, steps = 0).
//
//   Phase 1: each iteration increments steps by 1 and appends at most 1 token to
//   generated (EOS breaks without appending). |generated| grows by ≤1, steps grows by 1.
//
//   Phase 2 (OpenConstrainedSpan): appends the "<<" delimiter (1 token) and steps += 1.
//   |generated| grows by exactly 1, steps grows by exactly 1. Bound preserved.
//
//   Phase 3 — CloseConstrainedSpan: appends ">>" (1 token), steps += 1. Bound preserved.
//   Phase 3 — CloseSpanWithinBudget: let B = maxSteps − steps_before. Helper postcondition
//   gives |generated_new| ≤ |generated_old| + B. After steps := maxSteps,
//   |generated| ≤ |generatedPrefix| + steps_before + (maxSteps − steps_before)
//           = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//   Phase 3 — AdaptiveConstrainedStep: steps += 1, AppendConstrainedToken adds 1 token
//   (EOS branch breaks without appending). Bound preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step by step, using variable names such as n1, k2, p " +
  "(without curly braces). " +
  "When you have finished reasoning, write your answer as ONE complete arithmetic " +
  "expression inside a single << >> span. " +
  "Example: The answer is <<n1 * (k + 1) + n2>>. " +
  "Keep the expression complete and self-contained inside the ONE final << >> span.");

var steps: nat := 0;
// Reserve ~15% of the step budget for the constrained final-answer span.
var phase1Limit: nat := if maxSteps >= 20 then (maxSteps * 17) / 20 else 0;

// ── Phase 1: Unconstrained reasoning ──────────────────────────────────────────
// We deliberately do NOT check RenderedEndsWith here; we let the model write
// reasoning freely (including any natural << >> spans) without entering
// constrained mode. This avoids the 22-tiny-span collapse seen in attempt 63.
while steps < phase1Limit && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

// ── Phase 2: Force open exactly one constrained span for the final answer ─────
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// ── Phase 3: Generate the constrained answer; close when complete ─────────────
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    // Close the span now that the expression is complete.
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    // insideConstrainedOut is now false; loop exits on next check.
  } else if maxSteps - steps <= 3 {
    // Emergency close: prevent leaving the span open at budget exhaustion.
    var closeBudget: nat := maxSteps - steps;
    var fcg, fci, fcc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := fcg;
    insideConstrainedOut := fci;
    currentConstrainedOut := fcc;
    steps := maxSteps;
    // steps = maxSteps; loop exits.
  } else {
    // Normal constrained step: hard-mask to parser-valid tokens plus optional boosts.
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      validTokenGroups, 4.0, 12, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

cost := steps;

